import {mkdir, rm, cp, writeFile} from "node:fs/promises";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {site, nav, products, faqs, pages, giftCombinations, giftBoxes} from "../src/site-data.mjs";

const dist = new URL("../dist/", import.meta.url);
const distPath = fileURLToPath(dist);
const esc = s => String(s).replace(/[&<>\"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const link = (label, href, cls="") => `<a${cls?` class="${cls}"`:""} href="${href}">${label}</a>`;
const button = (label, href="/contact/") => `<a class="button" href="${href}"${href.startsWith("/contact/")?' data-conversion="quotation_request"':""}>${label}</a>`;
const outline = (label, href) => link(label, href, "button button--outline");
const icon = n => `<span class="mini-icon" aria-hidden="true">${n}</span>`;
const waNumber = "917303681194";
const waUrl = message => `https://wa.me/${waNumber}?text=${encodeURIComponent(message)}`;
const waIcon = `<svg class="wa-inline-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3a12 12 0 0 0-10.2 18.3L4 29l7.9-1.7A12 12 0 1 0 16 3Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11.1 9.8c.3-.6.6-.6 1-.6h.5c.2 0 .4.1.5.5l1 2.3c.1.3.1.5-.1.8l-.8 1c-.2.2-.3.4-.1.7.7 1.4 1.8 2.5 3.2 3.2.3.2.5.1.7-.1l1-1.2c.2-.3.5-.3.8-.2l2.4 1.1c.3.2.5.3.5.6 0 .3-.2 1.7-1.2 2.4-.7.6-1.7 1-3.1.6-1.5-.4-3.4-1.2-5.5-3.1-2-1.8-3.3-4.1-3.7-5.5-.4-1.4 0-2.2.4-2.8l.5-.7Z" fill="currentColor"/></svg>`;
const waLink = (label,message,cls="button button--whatsapp",ariaLabel="") => `<a class="${cls}" href="${waUrl(message)}" target="_blank" rel="noopener noreferrer" data-conversion="whatsapp_enquiry"${ariaLabel?` aria-label="${esc(ariaLabel)}"`:""}>${waIcon}<span>${label}</span></a>`;
const generalGiftMessage = "Hello House Of Brands, I am interested in your leather wallet and belt gift sets. Please share your catalogue, matching colour combinations, wholesale prices, packaging options and MOQ starting at 72 sets for qualifying configurations.";
const catalogueMessage = "Hello House Of Brands, I would like to receive your latest catalogue of 500+ leather wallet and accessories designs. Please share the available product range, colour options, private-label logo customization, branded packaging, MOQ and wholesale pricing.";

function header(){return `<a class="skip" href="#main">Skip to content</a><div class="utility"><div class="shell utility__inner"><span>India-based · Worldwide B2B enquiries</span><a href="mailto:${site.email}">${site.email}</a></div></div><header class="header"><div class="shell header__inner"><a class="brand" href="/" aria-label="Leather Wallet Manufacturer home"><span class="brand__mark">LW</span><span><b>Leather Wallet</b><small>Manufacturer</small></span></a><button class="menu" aria-expanded="false" aria-controls="primary-nav">Menu</button><nav id="primary-nav" class="nav" aria-label="Primary">${nav.map(([l,h])=>link(l,h)).join("")}${button("Request a quote")}</nav></div></header>`}
function footer(){return `<footer class="footer"><div class="shell footer__grid"><div><a class="brand brand--light" href="/"><span class="brand__mark">LW</span><span><b>Leather Wallet</b><small>Manufacturer</small></span></a><p>A private-label wallet development and sourcing platform operated by ${site.legalName}.</p><p><a href="mailto:${site.email}">${site.email}</a><br><a href="tel:${site.phone}">${site.phoneDisplay}</a><br><a href="${waUrl("Hello House Of Brands, I would like to discuss a leather wallet manufacturing enquiry.")}" target="_blank" rel="noopener noreferrer" data-conversion="whatsapp_enquiry">Enquire on WhatsApp</a></p></div><div><h3>Wallets</h3><a href="/wallet-collection/">500+ design catalogue</a><a href="/bifold-wallet-manufacturer/">Bifold wallets</a><a href="/trifold-wallet-manufacturer/">Trifold wallets</a><a href="/slim-wallet-manufacturer/">Slim wallets</a><a href="/cardholder-manufacturer/">Cardholders</a><a href="/leather-long-wallet-manufacturer/">Long wallets</a><a href="/zip-around-wallet-manufacturer/">Zip-around wallets</a></div><div><h3>Services</h3><a href="/private-label-wallet-manufacturer/">Private label</a><a href="/oem-wallet-manufacturer/">OEM development</a><a href="/wholesale-wallets/">Wholesale supply</a><a href="/low-moq-wallet-manufacturer/">Low MOQ</a><a href="/custom-logo-wallets/">Custom branding</a><a href="/custom-wallet-packaging/">Packaging</a></div><div><h3>Company</h3><a href="/leather-wallet-manufacturer-india/">India & international supply</a><a href="/corporate-gift-wallets/">Corporate gifting</a><a href="/leather-wallet-belt-gift-set-manufacturer/">Wallet & belt gift sets</a><a href="/resources/">Buyer guides</a><a href="/about-us/">About & founder</a><a href="/faq/">FAQ</a><a href="/contact/">Contact</a><a href="/privacy-policy/">Privacy</a><a href="/terms-and-conditions/">Terms</a></div></div><div class="shell footer__bottom"><span>© 2026 ${site.legalName}. All rights reserved.</span><span><a href="/contact/">Explore 500+ product designs</a> · MOQ and availability confirmed per project.</span></div></footer>`}
function schema(path, crumbs, faqItems=[]){const graph=[{"@type":"Organization","@id":`${site.url}/#org`,name:site.legalName,url:site.url,email:site.email,telephone:site.phone,founder:{"@id":`${site.url}/about-us/#rajan-mehta`}},{"@type":"WebSite","@id":`${site.url}/#website`,url:site.url,name:site.name,publisher:{"@id":`${site.url}/#org`},potentialAction:{"@type":"SearchAction",target:{"@type":"EntryPoint",urlTemplate:`${site.url}/wallet-collection/?q={search_term_string}`},"query-input":"required name=search_term_string"}},{"@type":"BreadcrumbList",itemListElement:crumbs.map((c,i)=>({"@type":"ListItem",position:i+1,name:c[0],item:`${site.url}${c[1]}`}))}];if(path==="/about-us/")graph.push({"@type":"Person","@id":`${site.url}/about-us/#rajan-mehta`,name:site.founder,jobTitle:"Founder & CEO",worksFor:{"@id":`${site.url}/#org`}});if(faqItems.length)graph.push({"@type":"FAQPage",mainEntity:faqItems.map(([q,a])=>({"@type":"Question",name:q,acceptedAnswer:{"@type":"Answer",text:a}}))});return JSON.stringify({"@context":"https://schema.org","@graph":graph});}
function layout({path,title,description,body,crumbs=[["Home","/"]],ogImage="wallet-collection-hero-branded-v2.jpg",faqItems=[]}){const canonical=`${site.url}${path}`; return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="${esc(site.name)}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${site.url}/assets/${ogImage}"><meta property="og:image:alt" content="Private-label leather wallet manufacturing and packaging concepts"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${site.url}/assets/${ogImage}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">${schema(path,crumbs,faqItems)}</script><script src="/site.js" defer></script></head><body>${header()}<main id="main">${body}</main>${footer()}<a class="whatsapp-fab" href="${waUrl("Hello House Of Brands, I would like to discuss a leather wallet manufacturing enquiry. Please share your catalogue, MOQ and customization options.")}" target="_blank" rel="noopener noreferrer" aria-label="Enquire on WhatsApp" data-tooltip="Chat with us on WhatsApp" data-conversion="whatsapp_enquiry"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3a12 12 0 0 0-10.2 18.3L4 29l7.9-1.7A12 12 0 1 0 16 3Z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M11.1 9.8c.3-.6.6-.6 1-.6h.5c.2 0 .4.1.5.5l1 2.3c.1.3.1.5-.1.8l-.8 1c-.2.2-.3.4-.1.7.7 1.4 1.8 2.5 3.2 3.2.3.2.5.1.7-.1l1-1.2c.2-.3.5-.3.8-.2l2.4 1.1c.3.2.5.3.5.6 0 .3-.2 1.7-1.2 2.4-.7.6-1.7 1-3.1.6-1.5-.4-3.4-1.2-5.5-3.1-2-1.8-3.3-4.1-3.7-5.5-.4-1.4 0-2.2.4-2.8l.5-.7Z" fill="currentColor"/></svg></a></body></html>`}
function crumbs(items){return `<nav class="breadcrumbs shell" aria-label="Breadcrumb">${items.map(([l,h],i)=>i===items.length-1?`<span aria-current="page">${l}</span>`:link(l,h)).join("<i>/</i>")}</nav>`}
function sectionHead(kicker,title,copy=""){return `<div class="section-head"><p class="eyebrow">${kicker}</p><h2>${title}</h2>${copy?`<p>${copy}</p>`:""}</div>`}
function cta(){return `<section class="final-cta"><div class="shell split"><div>${sectionHead("Start a conversation","Ready to build your own wallet collection?","Tell us your product direction, branding preferences, target quantity and market. We’ll help you explore a suitable route.")}</div><div class="button-row">${button("Request a wholesale quote")}${outline("Contact our team","/contact/")}</div></div></section>`}
function catalogueSection(){const benefits=[["Wide Product Selection","Explore 500+ product designs across relevant wallet and accessories collections."],["Private-Label Branding","Discuss embossed logos, debossing, foil branding and customized packaging."],["Wholesale Enquiries","Request pricing and MOQ information based on your selected products and requirements."]];return `<section class="section catalogue-section" id="product-catalogue"><div class="shell">${sectionHead("Explore 500+ Leather Wallet & Accessories Designs","500+ Designs. One Partner for Your Private-Label Wallet Range.","From classic bifold wallets and slim cardholders to coordinated wallet-and-belt gift sets, explore a broad range of styles and customization possibilities. Request our catalogue to review available designs, colours, branding options and packaging solutions.")}<div class="catalogue-benefits">${benefits.map(([title,copy],i)=>`<article><span>0${i+1}</span><h3>${title}</h3><p>${copy}</p></article>`).join("")}</div><p class="catalogue-qualification">The 500+ figure represents House Of Brands’ stated product range; individual availability and specifications are confirmed for each enquiry.</p><div class="button-row">${waLink("Request Product Catalogue",catalogueMessage,"button button--whatsapp","Request Catalogue on WhatsApp")}${button("Get Wholesale Pricing","/contact/")}${waLink("Chat on WhatsApp",catalogueMessage,"button button--outline","Enquire about the 500+ product catalogue on WhatsApp")}</div></div></section>`}
function catalogueCallout(){return `<section class="catalogue-callout"><div class="shell catalogue-callout__inner"><div><p class="eyebrow">500+ product designs</p><h2>Explore a broader private-label wallet and accessories range.</h2><p>Discover wallet styles, colours, finishes, coordinated gift sets, branding and packaging possibilities for B2B programmes. Availability is confirmed against your brief.</p></div><div class="button-row">${waLink("Get the Full Product Catalogue",catalogueMessage,"button button--whatsapp","Request Catalogue on WhatsApp")}${outline("View catalogue enquiry form","/contact/")}</div></div></section>`}
function process(){const steps=["Enquiry","Product selection","Specification","Branding & packaging","Sample approval, where applicable","Production","Quality checks","Dispatch"];return `<section class="section section--dark"><div class="shell">${sectionHead("A controlled route","From brief to dispatch.","Every project is defined by agreed specifications, approvals and commercial terms.")}<ol class="process">${steps.map((s,i)=>`<li><span>${String(i+1).padStart(2,"0")}</span>${s}</li>`).join("")}</ol></div></section>`}
function productGrid(){const groups=["men classic","men classic","men compact","compact unisex","women","women","women travel","branding","gifting"];return `<div class="catalogue-tools" aria-label="Catalogue filters"><label class="catalogue-search">Search product directions<input type="search" id="catalogue-search" placeholder="Try bifold, cardholder, women’s…" autocomplete="off"></label><div class="catalogue-filters" role="group" aria-label="Filter product directions"><button class="is-active" type="button" data-catalogue-filter="all">All</button><button type="button" data-catalogue-filter="men">Men’s</button><button type="button" data-catalogue-filter="women">Women’s</button><button type="button" data-catalogue-filter="compact">Compact</button><button type="button" data-catalogue-filter="branding">Custom branding</button><button type="button" data-catalogue-filter="gifting">Gifting</button></div><p class="catalogue-results" id="catalogue-results" aria-live="polite">Showing ${products.length} product directions</p></div><div class="product-grid" id="catalogue-grid">${products.map((p,i)=>`<article class="product-card tone-${p.tone}" data-catalogue-groups="${groups[i]}" data-catalogue-search="${esc(`${p.name} ${p.copy}`.toLowerCase())}"><div class="product-card__crop"><img src="/assets/wallet-styles-branded-v2.jpg" alt="Complete ${p.name.toLowerCase()} private-label concept showing logo, stitching and product edges" loading="lazy" width="1254" height="1254" style="--i:${i}"></div><div><p class="eyebrow">Direction ${String(i+1).padStart(2,"0")}</p><h3>${p.name}</h3><p>${p.copy}</p>${link("Explore & enquire →",`${p.href}?product=${encodeURIComponent(p.name)}`)}</div></article>`).join("")}</div><div class="catalogue-empty" id="catalogue-empty" hidden><h3>No matching direction is shown here yet.</h3><p>Try a broader search or request the full catalogue so the team can suggest relevant designs.</p>${button("Request the full catalogue","/contact/")}</div>`}
function faqBlock(limit=faqs.length){return `<div class="faq-list">${faqs.slice(0,limit).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join("")}</div>`}
function enquiryForm(){return `<form class="enquiry-form" id="enquiry-form" novalidate><div class="form-grid"><label>Full name*<input name="name" autocomplete="name" required></label><label>Company name<input name="company" autocomplete="organization"></label><label>Business email*<input name="email" type="email" autocomplete="email" required></label><label>Phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" placeholder="+ country code"></label><label>Country*<input name="country" autocomplete="country-name" required></label><label>Website or brand<input name="website" type="url" placeholder="https://"></label><label>Product category*<select name="product" required><option value="">Select</option>${["Men’s wallets","Women’s wallets","Bifold wallets","Cardholders","Corporate gifting","Other / custom"].map(x=>`<option>${x}</option>`).join("")}</select></label><label>Estimated quantity*<select name="quantity" required><option value="">Select</option><option>72–199 pieces</option><option>200–499 pieces</option><option>500–999 pieces</option><option>1,000+ pieces</option></select></label><label>Branding requirements<select name="branding"><option>To be discussed</option><option>Embossed / debossed logo</option><option>Foil / printed logo</option><option>Metal logo plate</option><option>No branding</option></select></label><label>Packaging requirements<input name="packaging" placeholder="Standard, branded box, gift set…"></label><label class="span-2">Enquiry message*<textarea name="message" rows="6" required placeholder="Tell us the wallet style, material direction, target market and timing."></textarea></label></div><label class="consent"><input type="checkbox" name="consent" required> I agree that ${site.legalName} may process my details to respond to this enquiry. See the <a href="/privacy-policy/">privacy policy</a>.</label><div class="form-actions"><button class="button" type="submit">Prepare email enquiry</button><p id="form-status" role="status">Submitting opens your email app with the project details. No information is stored on this website.</p></div></form>`}

function giftColourGrid(){return `<div class="filter-bar" role="group" aria-label="Filter colour combinations"><button class="is-active" data-filter="all">All combinations</button><button data-filter="matching">Matching colours</button><button data-filter="contrast">Contrast combinations</button><button data-filter="dark">Black & dark colours</button><button data-filter="tan">Tan & cognac</button><button data-filter="brown">Brown leather</button><button data-filter="premium">Premium colours</button></div><div class="gift-colour-grid">${giftCombinations.map((c,i)=>`<article class="gift-card" data-groups="${c.group}" data-combination="${c.name}"><div class="sheet-crop sheet-crop--3"><img class="sheet-cell-${c.cell}" src="/assets/gift-set-${c.sheet}-branded-v2.jpg" alt="Complete private-label concept of ${c.name}, showing the wallet, belt, buckle, logo and coordinated gift box" loading="lazy" width="1254" height="1254"></div><div class="gift-card__body"><span class="concept-label">Illustrative private-label concept</span><h3>${c.name}</h3><p>Wallet and belt colour, grain, finish, monogram treatment and material compatibility are confirmed before order.</p>${waLink("Ask about this combination",`Hello House Of Brands, I am interested in a wallet and belt gift set in the following colour combination: ${c.name}. Please share availability, branding options and pricing.`,"text-link whatsapp-context")}</div></article>`).join("")}</div>`}

function giftBoxGrid(){return `<div class="gift-box-grid">${giftBoxes.map(([name,copy],i)=>`<article class="box-card"><div class="sheet-crop sheet-crop--box"><img class="box-cell-${i}" src="/assets/gift-boxes-branded-v2.jpg" alt="Concept mockup for ${name}" loading="lazy" width="1536" height="1024"></div><div><span class="concept-label">Packaging concept</span><h3>${name}</h3><p>${copy}</p>${waLink("Enquire about this box","Hello House Of Brands, I am interested in custom-branded gift boxes for leather wallet and belt sets. Please share available box designs, logo application methods, pricing and minimum order requirements.","text-link whatsapp-context")}</div></article>`).join("")}</div>`}

function individualBoxGrid(){const boxes=[["Classic Rigid Box","A clean fitted presentation for an individual private-label wallet."],["Black Luxury Box","Black paper wrap with a restrained foil demonstration monogram."],["Espresso Blind-Embossed Box","Tonal, tactile branding paired with a coordinated dark-brown wallet."],["Warm-Ivory Brand Box","Understated dark branding and a premium retail presentation."],["Kraft Natural Box","Natural paperboard direction with a simple fitted wallet interior."],["Drawer-Style Box","Sliding tray construction with a fitted single-wallet insert."],["Magnetic-Closure Box","Hinged presentation format for a considered opening experience."],["Custom-Printed Retail Box","Brand colours and abstract artwork coordinated with the wallet."]];return `<div class="individual-box-grid">${boxes.map(([name,copy],i)=>`<article class="box-card"><div class="sheet-crop sheet-crop--individual"><img class="individual-cell-${i}" src="/assets/individual-wallet-boxes-branded-v2.jpg" alt="Private-label concept for ${name} with coordinated branded wallet" loading="lazy" width="1536" height="1024"></div><div><span class="concept-label">Illustrative private-label concept</span><h3>${name}</h3><p>${copy}</p>${waLink("Ask about this wallet box","Hello House Of Brands, I am interested in private-label leather wallets with my own embossed logo and custom-branded individual wallet boxes. Please share available options, pricing and MOQ.","text-link whatsapp-context")}</div></article>`).join("")}</div>`}

function whatsappEnquiryForm(){const colours=["Black","Dark brown","Tan","Cognac","Chocolate brown","Saddle tan","Caramel brown","Espresso brown","Burgundy","Navy","Olive","Need assistance"];return `<form class="enquiry-form" id="whatsapp-enquiry-form" novalidate><div class="form-grid"><label>Name*<input name="name" autocomplete="name" required></label><label>Company or brand name*<input name="company" autocomplete="organization" required></label><label>Business email*<input name="email" type="email" autocomplete="email" required></label><label>Country*<input name="country" autocomplete="country-name" required></label><label>Contact number<input name="phone" type="tel" autocomplete="tel"></label><label>Product interest*<select name="product" required><option value="">Select</option><option>Individual leather wallets</option><option>Private-label wallets</option><option>Wallets with branded individual boxes</option><option>Wallet and belt gift sets</option><option>Custom gift boxes</option><option>Corporate gifting</option></select></label><label>Wallet colour*<select name="walletColour" required><option value="">Select</option>${colours.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Belt colour, if applicable<select name="beltColour"><option>Not applicable</option>${colours.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Packaging preference*<select name="packaging" required><option value="">Select</option><option>Standard protective packaging</option><option>Branded individual wallet box</option><option>Branded wallet-and-belt gift box</option><option>Custom-printed retail packaging</option><option>Need assistance</option></select></label><label>Estimated quantity*<select name="quantity" required><option value="">Select</option><option>72–199 pieces or sets</option><option>200–499 pieces or sets</option><option>500–999 pieces or sets</option><option>1,000+ pieces or sets</option></select></label><label class="span-2">Logo branding requirements*<select name="branding" required><option value="">Select</option><option>Wallet embossing or debossing</option><option>Foil-stamped wallet logo</option><option>Branded individual wallet box</option><option>Branded wallet-and-belt gift box</option><option>Assistance selecting branding options</option></select></label><label class="span-2">Additional requirements<textarea name="message" rows="5" placeholder="Styles, colours, target market, timing or packaging requirements"></textarea></label></div><div class="form-actions"><button class="button button--whatsapp" type="submit">${waIcon}<span>Request Catalogue on WhatsApp</span></button><p id="whatsapp-form-status" role="status">Your selections will open in WhatsApp for review. Nothing is stored or sent automatically.</p></div></form>`}

function individualPackagingSection(){return `<section class="section section--cream individual-packaging"><div class="shell image-split"><img src="/assets/custom-wallet-packaging-branded-v2.jpg" alt="NORTH & HIDE demonstration wallet with matching branded individual wallet box and protective pouch" loading="lazy" width="1536" height="1024"><div>${sectionHead("Custom Wallet Boxes & Private-Label Packaging","Your Wallet Brand. Your Logo. Your Packaging.","Complete your private-label wallet collection with coordinated boxes, protective interiors and professional presentation for retail, gifting and wholesale programmes.")}<p>The photographed NORTH & HIDE identity is a fictional demonstration brand. Final box structure, print, insert, finish and logo application depend on the approved project.</p><div class="button-row">${button("Explore 8 wallet box concepts","/custom-wallet-packaging/#individual-wallet-boxes")}${waLink("Enquire about custom wallet boxes","Hello House Of Brands, I am interested in private-label leather wallets with my own embossed logo and custom-branded individual wallet boxes. Please share available options, pricing and MOQ.")}</div></div></div></section>`}

function individualPackagingCatalogue(){return `<section class="section" id="individual-wallet-boxes"><div class="shell">${sectionHead("Custom Wallet Boxes & Private-Label Packaging","Your Wallet Brand. Your Logo. Your Packaging.","Eight distinct single-wallet packaging concepts demonstrate coordinated branding across the wallet and its box.")}${individualBoxGrid()}<p class="packaging-note">These are illustrative private-label concepts, not confirmed production samples or client work. Materials, finishes, inserts, printing, logo application and minimum quantities remain subject to production feasibility and quotation.</p>${waLink("Enquire About Custom Wallet Boxes","Hello House Of Brands, I am interested in private-label leather wallets with my own embossed logo and custom-branded individual wallet boxes. Please share available options, pricing and MOQ.")}</div></section>`}

function giftSetForm(){const colours=["Black","Dark brown","Tan","Cognac","Chocolate brown","Saddle tan","Caramel brown","Espresso brown","Burgundy","Navy","Olive","Need assistance"];return `<form class="enquiry-form gift-set-form" id="gift-set-form" novalidate><div class="form-grid"><label>Name*<input name="name" autocomplete="name" required aria-describedby="gift-form-status"></label><label>Company or brand*<input name="company" autocomplete="organization" required></label><label>Business email*<input name="email" type="email" autocomplete="email" required></label><label>Country*<input name="country" autocomplete="country-name" required></label><label>WhatsApp or contact number<input name="phone" type="tel" autocomplete="tel"></label><label>Preferred wallet colour*<select name="walletColour" required><option value="">Select</option>${colours.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Preferred belt colour*<select name="beltColour" required><option value="">Select</option>${colours.map(x=>`<option>${x}</option>`).join("")}</select></label><label>Gift box style*<select name="box" required><option value="">Select</option>${giftBoxes.map(([x])=>`<option>${x}</option>`).join("")}</select></label><label>Quantity*<select name="quantity" required><option value="">Select</option><option>72–199 sets</option><option>200–499 sets</option><option>500–999 sets</option><option>1,000+ sets</option></select></label><label>Branding requirements*<select name="branding" required><option value="">Select</option><option>Wallet logo</option><option>Belt branding, where feasible</option><option>Gift box logo</option><option>Custom packaging</option><option>Multiple branding requirements</option><option>Need assistance selecting options</option></select></label><label class="span-2">Additional message<textarea name="message" rows="5" placeholder="Target market, timing, reference style or other requirements"></textarea></label></div><div class="form-actions"><button class="button button--whatsapp" type="submit">Continue on WhatsApp</button><p id="gift-form-status" role="status">Your selections will open in WhatsApp for review. You choose whether to send the message.</p></div></form>`}

function home(){return layout({path:"/",title:"Leather Wallet Manufacturer | India OEM & Private Label",description:"Leather wallet manufacturer for private-label, OEM and wholesale B2B programmes, with 500+ designs and selected MOQ options from 72 pieces.",body:`<section class="hero"><div class="hero__media"><img src="/assets/wallet-collection-hero-branded-v2.jpg" alt="Private-label branded leather bifold wallets and cardholders in black, cognac, oxblood and olive" width="1672" height="941"></div><div class="shell hero__content"><p class="eyebrow">OEM · Private label · Custom branding</p><h1>Leather Wallet Manufacturer in India <em>for brands worldwide.</em></h1><p class="hero__lead">Build your own wallet brand with a low MOQ starting at 72 pieces.</p><p>From wallet selection and custom branding to personalized packaging and coordinated supply, we help businesses develop wallet collections tailored to their brand and market.</p><div class="button-row">${button("Get wholesale pricing")}${outline("Explore wallet collection","/wallet-collection/")}</div></div><div class="shell proof-strip">${["MOQ starting at 72 pieces","Private label & OEM","Custom branding & packaging","Worldwide B2B enquiries"].map((x,i)=>`<span>${icon(i+1)}${x}</span>`).join("")}</div></section><section class="section"><div class="shell">${sectionHead("The advantage","A focused route from product to presentation.","Build a commercially coherent wallet programme without treating design, branding and packaging as separate decisions.")}<div class="value-grid">${[["72+","Low MOQ for growing brands"],["OEM","Private label & development"],["Logo","Branding with intent"],["Global","Supply coordination"]].map(([a,b])=>`<article><strong>${a}</strong><h3>${b}</h3><p>Scope and feasibility are confirmed against the chosen product, quantity and destination.</p></article>`).join("")}</div></div></section><section class="section section--cream"><div class="shell">${sectionHead("Wallet collection","Start with the silhouette. Build the specification.","Representative directions help frame the discussion; current products and specifications are confirmed before quotation.")}${productGrid()}<p class="disclosure">Product imagery uses fictional demonstration branding to illustrate private-label possibilities; it is not presented as client work or a confirmed production sample. Material, colour, construction and availability are confirmed for each enquiry.</p></div></section><section class="section editorial"><div class="shell split"><div><p class="eyebrow">Private label manufacturing</p><h2>Your brand. Your wallet collection. Your specifications.</h2><p>We help buyers choose a suitable route, align the product and commercial brief, approve brand-visible details and coordinate the agreed production and supply process.</p>${button("Discuss your private-label project","/private-label-wallet-manufacturer/")}</div><ol class="number-list">${["Discuss product requirements","Select a design or explore a custom concept","Agree material, colour and finish","Finalize logo placement and branding","Confirm packaging requirements","Approve samples where applicable","Confirm commercial terms and production","Coordinate checks and dispatch"].map((x,i)=>`<li><span>${String(i+1).padStart(2,"0")}</span>${x}</li>`).join("")}</ol></div></section><section class="moq-band"><div class="shell moq-band__grid"><div><span class="mega">72</span><span class="mega-label">pieces<br>starting MOQ</span></div><div><p class="eyebrow">A practical first collection</p><h2>Launch with focus, then scale with evidence.</h2><p>Selected wallet programmes can begin from 72 pieces. Final minimums depend on the product, materials, colour split, customization and packaging.</p>${outline("Get pricing for 72 pieces","/low-moq-wallet-manufacturer/")}</div></div></section><section class="section"><div class="shell image-split"><img src="/assets/custom-wallet-packaging-branded-v2.jpg" alt="Private-label branded cognac wallet with coordinated branded cream packaging" loading="lazy" width="1536" height="1024"><div>${sectionHead("Branding & packaging","The details customers remember.","Discuss a suitable logo method, placement, packaging structure and printed collateral—each subject to project feasibility.")}<div class="chip-row">${["Embossing","Debossing","Foil stamping","Printing","Metal plates","Labels & inserts"].map(x=>`<span>${x}</span>`).join("")}</div><div class="button-row">${button("Customize your wallet","/custom-logo-wallets/")}${outline("Discuss packaging","/custom-wallet-packaging/")}</div></div></div></section>${process()}<section class="section seo-copy"><div class="shell split"><div>${sectionHead("B2B manufacturing partner","Leather wallet manufacturing for wholesale and brand programmes.","House Of Brands supports buyers seeking a leather wallet supplier, bulk leather wallet supplier or leather wallet manufacturing company for defined commercial projects.")}<p>The manufacturing and sourcing route is coordinated around the approved specification; the website does not imply ownership of every leather wallet factory involved in a project. Materials, origin details, production route and commercial terms are confirmed in writing.</p></div><div><h3>Choose the route that fits the brief</h3><p>Use <a href="/private-label-wallet-manufacturer/">private-label wallet manufacturing</a> to adapt suitable platforms, <a href="/oem-wallet-manufacturer/">OEM development</a> for deeper customization, or <a href="/wholesale-wallets/">wholesale wallet supply</a> for assortment-led enquiries.</p><h3>India and international enquiries</h3><p>Importers, distributors and international brands can review <a href="/leather-wallet-manufacturer-india/">India-based manufacturing and export coordination</a>, including destination and documentation considerations.</p></div></div></section><section class="section"><div class="shell founder"><img src="/assets/rajan-mehta-founder-house-of-brands.jpg" alt="Rajan Mehta, Founder and CEO of House Of Brands Fashion LLP" loading="lazy" width="900" height="1600"><div>${sectionHead("Built on experience. Driven by brands.","A founder-led approach to product development and global sourcing.")}<p>Rajan Mehta is Founder & CEO of ${site.legalName}, with over 25 years of experience across watches, fashion accessories, product development, private label, sourcing, packaging and retail strategy.</p><p>A Mechanical Engineer from REC Kurukshetra and MBA from IIM Calcutta, his professional experience spans India, Europe, the Middle East and China.</p><div class="credential-row"><span>25+ years</span><span>REC Kurukshetra</span><span>IIM Calcutta</span></div>${outline("Meet the founder","/about-us/")}</div></div></section><section class="section section--cream"><div class="shell story">${sectionHead("House Of Brands","From product expertise to brand partnerships.","House Of Brands supports businesses through product development, sourcing, manufacturing coordination, packaging and supply-chain execution across consumer categories.")}<div class="timeline"><article><span>01</span><h3>Foundations</h3><p>Consumer products, category knowledge and trusted sourcing relationships.</p></article><article><span>02</span><h3>Expansion</h3><p>Fashion accessories, private-label partnerships and marketplace programmes.</p></article><article><span>03</span><h3>Today</h3><p>Brand-focused product development and coordinated supply for growing businesses.</p></article></div><a href="https://houseofbrands.in/" rel="noopener">Discover House Of Brands ↗</a></div></section><section class="section"><div class="shell faq-layout"><div>${sectionHead("Frequently asked","Clear answers before you enquire.")} ${outline("View all questions","/faq/")}</div>${faqBlock(6)}</div></section>${cta()}`});}

function relatedLinks(p){return p.related?.length?`<nav class="related-links" aria-label="Related services"><h2>Related products and services</h2><div>${p.related.map(([label,href])=>link(label,href)).join("")}</div></nav>`:""}
function generic(p){const isCollection=p.type==="collection";const isPackaging=p.type==="packaging";const image=isPackaging?"custom-wallet-packaging-branded-v2.jpg":"wallet-styles-branded-v2.jpg";const imageWidth=isPackaging?1536:1254;const imageHeight=isPackaging?1024:1254;const message=`Hello House Of Brands, I am interested in ${p.primary}. Please share suitable product options, private-label branding, packaging, MOQ, wholesale pricing and availability for my market.`;return layout({path:p.path,title:p.title,description:p.description||p.intro,crumbs:[["Home","/"],[p.eyebrow,p.path]],body:`${crumbs([["Home","/"],[p.eyebrow,p.path]])}<section class="page-hero"><div class="shell page-hero__grid"><div><p class="eyebrow">${p.eyebrow}</p><h1>${p.h1}</h1><p class="lede">${p.intro}</p><div class="button-row">${waLink(p.cta||"Discuss Your Project",message)}${outline("View wallet collection","/wallet-collection/")}</div></div><img src="/assets/${image}" alt="Complete illustrative ${p.primary} concept with visible product edges and private-label branding" width="${imageWidth}" height="${imageHeight}"></div></section><section class="section"><div class="shell">${isCollection?`${sectionHead("Product directions","A collection built for your brief.","Choose a starting point, then define the specification that supports your customer, channel and price position.")}${productGrid()}`:`<div class="feature-panel"><div>${sectionHead("Project scope","Define what matters before production.","A useful quotation depends on a clear product, brand and commercial brief.")}<p>We distinguish between selected private-label platforms and deeper custom development. Materials are identified accurately, and branding or packaging options are not treated as included until confirmed in writing.</p></div><ul>${p.bullets.map(x=>`<li>${x}</li>`).join("")}</ul></div>`}</div></section>${p.seoHeading?`<section class="section seo-copy section--cream"><div class="shell split"><div>${sectionHead(p.primary,p.seoHeading,p.seoCopy)}</div><div><h3>What to include in your enquiry</h3><p>Share the intended market, product format, material direction, colour, quantity, logo artwork, packaging preference, destination and required timing. This allows feasibility, MOQ and pricing to be assessed against a real scope.</p><p>The stated range of 500+ designs represents the broader catalogue; individual styles, colours, branding methods and packaging options are confirmed per enquiry.</p></div></div></section>`:""}${p.type==="packaging"||p.type==="branding"?`<section class="section"><div class="shell image-split"><img src="/assets/custom-wallet-packaging-branded-v2.jpg" alt="Private-label wallet with coordinated customizable branded packaging" loading="lazy" width="1536" height="1024"><div>${sectionHead("Approval matters","From artwork to a controlled result.","Method, size, placement, colour and substrate all affect the final execution. Packaging can introduce its own supplier minimums, tooling and freight implications.")}<p>Digital artwork review establishes the direction. A physical sample or production approval route is agreed where applicable before the bulk order proceeds.</p></div></div></section>`:""}${relatedLinks(p)}${process()}<section class="section section--cream"><div class="shell faq-layout"><div>${sectionHead("Questions to resolve","A quotation that reflects the real project.")}<p>Share the target customer, destination, wallet direction, quantity, material preference, logo artwork and packaging needs.</p></div>${faqBlock(4)}</div></section>${cta()}`});}

function giftSetPage(){return layout({path:"/leather-wallet-belt-gift-set-manufacturer/",title:"Leather Wallet & Belt Gift Set Manufacturer India | Private Label",description:"Wholesale leather wallet and belt gift sets with custom branding, premium gift boxes and low MOQ starting at 72 qualifying sets.",crumbs:[["Home","/"],["Wallet & belt gift sets","/leather-wallet-belt-gift-set-manufacturer/"]],ogImage:"wallet-belt-gift-set-branded-v2.jpg",body:`${crumbs([["Home","/"],["Wallet & belt gift sets","/leather-wallet-belt-gift-set-manufacturer/"]])}<section class="gift-hero"><div class="gift-hero__media"><img src="/assets/wallet-belt-gift-set-branded-v2.jpg" alt="Concept mockup of a coordinated cognac leather wallet and belt in a premium gift box" width="1672" height="941"></div><div class="shell gift-hero__content"><p class="eyebrow">OEM · Private label · Wholesale</p><h1>Leather Wallet & Belt Gift Set Manufacturer in India</h1><p class="lede">Create premium private-label wallet and belt gift sets with coordinated leather colours, custom embossed branding and elegant gift packaging. Wholesale and OEM solutions with low MOQ starting at 72 sets for qualifying configurations.</p><div class="moq-pill">Low MOQ: Starting at 72 Gift Sets</div><p class="qualification">For qualifying configurations. Final minimums depend on products, materials, branding, packaging and customization.</p><div class="button-row">${waLink("Get gift set wholesale pricing",generalGiftMessage)}${outline("Explore gift box options","#gift-boxes")}</div></div></section><section class="section"><div class="shell"><div class="feature-panel"><div>${sectionHead("A coordinated offer","One gift set. Every detail considered.","Develop a wallet, belt and packaging presentation around the customer, occasion and commercial brief.")}<p>House Of Brands supports wholesale buyers, private-label brands, retailers, distributors, corporate gifting companies and promotional businesses. The selected wallet and belt are considered together for colour direction, finish, branding and presentation.</p></div><ul><li>Matching or contrast colour directions</li><li>Private-label wallet and belt branding</li><li>Retail and corporate gift packaging</li><li>Worldwide enquiries subject to feasibility</li></ul></div></div></section><section class="section section--cream" id="colour-combinations"><div class="shell">${sectionHead("Colour combination catalogue","Natural, classic and premium leather directions.","Explore 18 proposed merchandising combinations. These are concept visuals—not confirmed production samples. Actual colours, finishes, materials and availability must be approved before order.")}${giftColourGrid()}<p class="disclosure">Displayed colours are illustrative. Final leather colour, finish, material availability and matching options will be confirmed before production.</p></div></section><section class="moq-band"><div class="shell moq-band__grid"><div><span class="mega">72</span><span class="mega-label">gift sets<br>starting MOQ</span></div><div><p class="eyebrow">Low MOQ, appropriately qualified</p><h2>A practical starting point for focused gifting programmes.</h2><p>Suitable for emerging brands, retailers, corporate gifting businesses and established private-label buyers. A 72-set starting quantity applies only to qualifying configurations and does not guarantee every colour, material, branding method or custom box at that quantity.</p>${waLink("Check 72-set eligibility",generalGiftMessage,"button button--light")}</div></div></section><section class="section" id="gift-boxes"><div class="shell">${sectionHead("Premium Gift Boxes for Wallet & Belt Sets","Choose coordinated packaging that reflects your brand identity, gifting programme or retail positioning.","Ten distinct directions provide a practical starting point for construction, presentation, finish and artwork discussions.")}${giftBoxGrid()}<p class="packaging-note">Packaging styles, materials, logo application, inserts and finishing options are subject to customization, minimum order requirements and production feasibility. Final specifications will be confirmed during quotation.</p><div class="button-row">${waLink("Enquire About Custom Gift Packaging","Hello House Of Brands, I am interested in custom-branded gift boxes for leather wallet and belt sets. Please share available box designs, logo application methods, pricing and minimum order requirements.")}${outline("Explore packaging services","/custom-wallet-packaging/")}</div></div></section><section class="section section--dark"><div class="shell split"><div>${sectionHead("Private label gift sets","Develop a set around your brand.","Coordinate product, logo treatment, box construction and printed collateral as one branded presentation.")}<p>Branding on the wallet, belt and packaging is assessed for feasibility against the selected material, artwork, construction and quantity. Sampling and approvals are agreed for the project.</p><div class="button-row">${waLink("Discuss a private-label set","Hello House Of Brands, I would like to develop a private-label leather wallet collection with my own embossed logo and branded individual packaging. Please share product options, branding methods, packaging choices, MOQ and wholesale pricing.","button button--light")}${outline("Private-label services","/private-label-wallet-manufacturer/")}</div></div><ol class="number-list number-list--light"><li><span>01</span>Define the customer and occasion</li><li><span>02</span>Select wallet and belt directions</li><li><span>03</span>Align materials and colours</li><li><span>04</span>Approve logo and packaging route</li><li><span>05</span>Confirm samples and commercial terms</li></ol></div></section><section class="section section--cream"><div class="shell contact-grid"><div>${sectionHead("Gift set quotation","Build your enquiry, then continue on WhatsApp.","The form creates a readable message from your selections. Nothing is submitted to a database or CRM.")}<p>Include the intended market, quantity, wallet and belt colours, gift box direction and branding requirements. WhatsApp opens with the summary prefilled for your review.</p><div class="contact-card"><span>Starting MOQ</span><strong>72 qualifying gift sets</strong><span>Business WhatsApp</span><a href="${waUrl(generalGiftMessage)}" target="_blank" rel="noopener noreferrer">${site.phoneDisplay}</a></div></div>${giftSetForm()}</div></section>${cta()}`});}

function homeGiftSection(){return `<section class="section home-gift"><div class="shell image-split"><img src="/assets/wallet-belt-gift-set-branded-v2.jpg" alt="Concept mockup of a cognac leather wallet and matching belt in a premium gift box" loading="lazy" width="1672" height="941"><div>${sectionHead("Wallet & belt gift sets","A coordinated gift, built around your brand.","Explore matching and contrast leather colour directions, private-label branding and premium packaging for retail, corporate and wholesale programmes.")}<div class="moq-pill">Low MOQ: Starting at 72 Gift Sets</div><p class="qualification">Applies to qualifying configurations; product, material, branding and box feasibility are confirmed during quotation.</p><div class="button-row">${button("Explore wallet & belt gift sets","/leather-wallet-belt-gift-set-manufacturer/")}${waLink("WhatsApp for wholesale pricing",generalGiftMessage,"button button--whatsapp")}</div><span class="concept-label">Representative concept visual</span></div></div></section>`}

function homeExtended(){return home().replace(`${outline("Explore wallet collection","/wallet-collection/")}</div>`,`${outline("Explore wallet collection","/wallet-collection/")}${waLink("WhatsApp enquiry","Hello House Of Brands, I am interested in your private-label leather wallets. Please share your catalogue, wholesale pricing, logo embossing options, individual wallet box options and MOQ.","button button--whatsapp")}</div>`).replace(`<section class="section editorial">`,`${homeGiftSection()}<section class="section editorial">`).replace(`${button("Discuss your private-label project","/private-label-wallet-manufacturer/")}`,`${button("Discuss your private-label project","/private-label-wallet-manufacturer/")}${waLink("Private-label WhatsApp","Hello House Of Brands, I would like to develop a private-label leather wallet collection with my own embossed logo and branded individual packaging. Please share product options, branding methods, packaging choices, MOQ and wholesale pricing.","text-link whatsapp-context")}`)}

function genericExtended(p){return generic(p)}

function buyerResourcesSection(){const guides=[["01","Launch a private-label wallet collection","Define the customer, opening assortment, product route, branding, packaging and approval sequence before requesting prices."],["02","Understand MOQ before you commit","See how product choice, material, colour splits, logo methods and packaging can each affect the confirmed minimum."],["03","Plan logo branding and packaging","Compare embossing, debossing, foil and coordinated presentation without assuming every method suits every product."]];return `<section class="section buyer-resources"><div class="shell"><div class="resource-heading">${sectionHead("Buyer resources","Make a stronger sourcing decision before you request a quote.","Practical guidance for founders, procurement teams, retailers and importers planning a wallet programme.")}${outline("Explore all buyer guides","/resources/")}</div><div class="resource-grid">${guides.map(([n,title,copy])=>`<article><span>${n}</span><h3>${title}</h3><p>${copy}</p><a href="/resources/#guide-${n}">Read the guide →</a></article>`).join("")}</div></div></section>`}

function homeFinal(){const html=homeExtended().replace(homeGiftSection(),`${individualPackagingSection()}${homeGiftSection()}${catalogueSection()}`).replace("Build your own wallet brand with a low MOQ starting at 72 pieces.","Explore 500+ leather wallet and accessories designs, with selected private-label programmes starting at 72 pieces.");const faqStart=html.lastIndexOf(`<section class="section"><div class="shell faq-layout">`);return faqStart===-1?`${html}${buyerResourcesSection()}`:`${html.slice(0,faqStart)}${buyerResourcesSection()}${html.slice(faqStart)}`}

function genericFinal(p){let html=genericExtended(p);if(p.path==="/custom-wallet-packaging/")html=html.replace(`<section class="section section--dark">`,`${individualPackagingCatalogue()}<section class="section section--dark">`);if(["/wallet-collection/","/private-label-wallet-manufacturer/"].includes(p.path))html=html.replace(`<section class="section section--dark">`,`${catalogueCallout()}<section class="section section--dark">`);return html}

function giftSetSeoSection(){return `<section class="section seo-copy"><div class="shell split"><div>${sectionHead("Wallet and belt gift set wholesale","Gift-set supply for retail, private label and corporate programmes.","House Of Brands supports wallet and belt gift set wholesale enquiries, including matching or contrasting colours, custom logo treatment and coordinated presentation boxes.")}<p>A private label wallet and belt gift set or custom wallet and belt gift set is scoped as a complete programme. Wallet, belt, buckle, logo application, insert and gift box choices must be commercially compatible.</p></div><div><h3>Custom-branded wallet and belt gift sets</h3><p>Buyers can discuss a branded wallet and belt gift set, custom logo wallet and belt set, or custom branded wallet belt gift box. Availability, tooling and minimums depend on the selected configuration.</p><h3>Wholesale and corporate supply</h3><p>The range is relevant to retailers, distributors and buyers planning wallet and belt corporate gift sets or wholesale leather gift sets. The 72-set starting point applies only to qualifying configurations.</p></div></div></section>`}
function giftSetPageFinal(){return giftSetPage().replace(`${cta()}`,`${giftSetSeoSection()}${catalogueCallout()}${cta()}`)}

function resourcesPage(){const guides=[
  ["01","How to launch a private-label wallet collection","Start with the intended customer, channel and opening price architecture. Choose a focused assortment rather than too many overlapping silhouettes. Decide whether an existing platform with your branding is sufficient or whether the project needs deeper OEM development. Prepare logo artwork, packaging direction, target quantity, destination and required timing before requesting a quotation."],
  ["02","How to choose wallet styles for a retail collection","Build a clear good-better-best structure. A core bifold, a reduced-profile option and a cardholder can cover distinct use cases without unnecessary duplication. Add women’s, long or zip-around formats only when they serve the intended customer. Ask how materials, interiors and packaging affect both the product experience and the commercial brief."],
  ["03","Understanding MOQ for customized wallets","MOQ is not a single website-wide promise. Product construction, material availability, colour splits, logo tooling, packaging supplier minimums and production planning all influence it. Selected programmes may start at 72 pieces, but the applicable minimum must be confirmed against the exact configuration."],
  ["04","Embossing, debossing and other logo methods","Blind impressions create a tonal mark; foil adds contrast; printing may suit selected materials; metal plates introduce hardware and attachment considerations. Artwork detail, logo size, placement, substrate and order quantity determine which method is practical. Approve the method and placement before bulk production."],
  ["05","How to plan branded wallet packaging","Treat the wallet and its packaging as one retail system. Define protection, opening experience, insert structure, artwork, printed collateral, transit needs and disposal expectations. Packaging can have different tooling, lead-time and minimum requirements from the wallet, so scope it early rather than after product approval."],
  ["06","Questions to ask before placing a bulk order","Confirm the written product specification, material description, approved sample route, logo artwork, packaging scope, quantity split, commercial terms, inspection approach, destination documentation and dispatch responsibilities. Record changes in writing so the quotation and approval trail stay aligned."],
  ["07","Planning a wallet-and-belt gift set","Evaluate wallet and belt colour, finish, hardware, buckle, sizing approach, logo treatment, insert and box as a complete programme. Matching colours are a direction, not a guarantee of identical shade across different material lots. Confirm the approved visual and commercial scope before production."]
];return layout({path:"/resources/",title:"Leather Wallet Buyer Guides | Private Label & Wholesale",description:"Practical B2B guides for planning private-label wallets, MOQ, logo branding, packaging, bulk orders and wallet-and-belt gift sets.",crumbs:[["Home","/"],["Buyer guides","/resources/"]],body:`${crumbs([["Home","/"],["Buyer guides","/resources/"]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">B2B buyer resources</p><h1>Plan a stronger leather wallet sourcing brief.</h1><p class="lede">Use these practical guides to define the product, branding, packaging and commercial questions that should be resolved before a bulk or private-label order.</p></div></section><section class="section section--cream"><div class="shell guide-index"><p class="eyebrow">In this guide</p><nav aria-label="Buyer guide topics">${guides.map(([n,title])=>`<a href="#guide-${n}"><span>${n}</span>${title}</a>`).join("")}</nav></div></section><section class="section"><div class="shell guide-list">${guides.map(([n,title,copy])=>`<article id="guide-${n}"><span>${n}</span><div><h2>${title}</h2><p>${copy}</p><div class="guide-actions">${n==="01"?link("Explore private-label manufacturing →","/private-label-wallet-manufacturer/"):n==="02"?link("Browse wallet directions →","/wallet-collection/"):n==="03"?link("Review low-MOQ programmes →","/low-moq-wallet-manufacturer/"):n==="04"?link("Compare branding options →","/custom-logo-wallets/"):n==="05"?link("Explore packaging concepts →","/custom-wallet-packaging/"):n==="07"?link("Explore gift sets →","/leather-wallet-belt-gift-set-manufacturer/"):link("Prepare a quotation request →","/contact/")}</div></div></article>`).join("")}</div></section>${cta()}`});}

function about(){return layout({path:"/about-us/",title:"About House Of Brands | Leather Wallet Development",description:"Meet Rajan Mehta and House Of Brands Fashion LLP, the team behind LeatherWalletManufacturer.com.",crumbs:[["Home","/"],["About","/about-us/"]],body:`${crumbs([["Home","/"],["About","/about-us/"]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">About House Of Brands</p><h1>Product expertise, brand judgement and a global sourcing perspective.</h1><p class="lede">LeatherWalletManufacturer.com extends House Of Brands’ private-label and product development approach to wallet collections for Indian and international B2B buyers.</p></div></section><section class="section"><div class="shell founder founder--large"><img src="/assets/rajan-mehta-founder-house-of-brands.jpg" alt="Rajan Mehta, Founder and CEO of House Of Brands Fashion LLP" width="900" height="1600"><div>${sectionHead("Founder & CEO","Rajan Mehta","A founder-led approach to product development, manufacturing coordination and global sourcing.")}<p>Rajan brings over 25 years of experience in the global watch, fashion accessories and lifestyle industry. His work has included product development, private-label manufacturing, sourcing, packaging innovation and retail strategy across India, Europe, the Middle East and China.</p><p>He completed Mechanical Engineering at REC Kurukshetra and an MBA at IIM Calcutta. That combination of technical thinking and commercial discipline shapes how House Of Brands evaluates products, suppliers, packaging and route-to-market decisions.</p><p><a href="https://rajanmehta.in/" rel="noopener">Connect with our founder ↗</a><br><a href="https://rajanmehta.in/about" rel="noopener">Explore Rajan Mehta’s professional background ↗</a></p></div></div></section><section class="section section--cream"><div class="shell story">${sectionHead("Our story","From product expertise to brand partnerships.","House Of Brands works with businesses to develop, source and scale consumer products through private-label solutions, product development, manufacturing coordination, packaging and supply-chain execution.")}<div class="timeline"><article><span>01</span><h3>Product foundations</h3><p>Deep category knowledge and an understanding of consumer, retail and marketplace requirements.</p></article><article><span>02</span><h3>Private-label partnerships</h3><p>Bringing together the product, manufacturing route, brand layer, packaging and commercial brief.</p></article><article><span>03</span><h3>Wallet development</h3><p>A focused route for wallet sourcing and customized solutions, with selected programmes starting at 72 pieces.</p></article></div><p>We do not present this website as owning every production facility. The manufacturing and sourcing route is coordinated around the approved specification and confirmed project capabilities.</p></div></section>${cta()}`});}
function contact(){return layout({path:"/contact/",title:"Request a Wallet Manufacturing Quote | Contact",description:"Share your wallet type, quantity, branding, packaging and destination for a project-specific B2B quotation.",crumbs:[["Home","/"],["Contact","/contact/"]],body:`${crumbs([["Home","/"],["Contact","/contact/"]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">Global project enquiry</p><h1>Tell us what you want to build.</h1><p class="lede">Share your product direction, quantity, destination, branding and packaging requirements. We’ll use that context to discuss a suitable route.</p></div></section><section class="section section--cream"><div class="shell contact-grid"><div>${sectionHead("Request a quotation","A better brief creates a better first response.")}<p>Include reference images or a specification by replying to the prepared email after the form opens your email app.</p><div class="contact-card"><span>Email</span><a href="mailto:${site.email}">${site.email}</a><span>Phone / WhatsApp</span><a href="https://wa.me/${site.phone.replace("+","")}" rel="noopener">${site.phoneDisplay}</a><small>Business contact details verified from House Of Brands and WatchesManufacturer.com.</small></div></div>${enquiryForm()}</div></section>`});}
function contactExtended(){return contact().replace(`<a href="https://wa.me/${site.phone.replace("+","")}" rel="noopener">${site.phoneDisplay}</a>`,`<a href="${waUrl("Hello House Of Brands, I would like to discuss a leather wallet or wallet-and-belt gift set enquiry. Please share the relevant catalogue, MOQ and customization options.")}" target="_blank" rel="noopener noreferrer">${site.phoneDisplay} · Start WhatsApp enquiry</a>`)}
function contactWhatsApp(){return layout({path:"/contact/",title:"Request the 500+ Wallet Product Catalogue | WhatsApp",description:"Request the latest leather wallet and accessories catalogue, private-label branding options, MOQ and wholesale pricing on WhatsApp.",crumbs:[["Home","/"],["Contact","/contact/"]],body:`${crumbs([["Home","/"],["Contact","/contact/"]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">500+ designs · Global B2B enquiries</p><h1>Request the full leather wallet and accessories catalogue.</h1><p class="lede">Share your requirements for individual wallets, private-label collections, branded wallet boxes, wallet-and-belt gift sets or corporate gifting.</p></div></section><section class="section section--cream"><div class="shell contact-grid"><div>${sectionHead("Request Catalogue on WhatsApp","A structured first conversation.","Your selections create a readable catalogue request in WhatsApp. Nothing is stored in a database or sent until you review and send it yourself.")}<p>Explore the stated range of 500+ product designs, colours, finishes and private-label possibilities. Individual availability is confirmed for each enquiry.</p><div class="contact-card"><span>Business email</span><a href="mailto:${site.email}">${site.email}</a><span>WhatsApp catalogue request</span><a href="${waUrl(catalogueMessage)}" target="_blank" rel="noopener noreferrer">${site.phoneDisplay}</a><span>Low MOQ</span><strong>Starting at 72 qualifying pieces or sets</strong></div></div>${whatsappEnquiryForm()}</div></section>`})}
function faqPage(){return layout({path:"/faq/",title:"Leather Wallet Manufacturing FAQ | MOQ & Branding",description:"Answers about wallet MOQ, private label, custom logos, packaging, sampling, materials and international supply.",crumbs:[["Home","/"],["FAQ","/faq/"]],faqItems:faqs,body:`${crumbs([["Home","/"],["FAQ","/faq/"]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">Buyer questions</p><h1>Leather wallet manufacturing questions for B2B buyers.</h1><p class="lede">Exact feasibility, pricing and timing follow the approved product specification and commercial terms.</p></div></section><section class="section"><div class="shell narrow">${faqBlock()}</div></section>${cta()}`});}
function policy(kind){const privacy=kind==="privacy"; const path=privacy?"/privacy-policy/":"/terms-and-conditions/"; const h=privacy?"Privacy policy":"Terms and conditions"; const sections=privacy?[["Information we receive","When you contact us, we may receive your name, company, email, phone, country and project information."],["How it is used","Information is used to respond to enquiries, evaluate projects, maintain business records and meet legal obligations."],["Sharing and retention","Information may be shared with service providers or project partners only as needed for the enquiry, subject to appropriate safeguards. It is retained only as reasonably necessary."],["Your choices","You may request access, correction or deletion by emailing the contact below, subject to applicable law and legitimate record-keeping needs."]]:[["Website information","Content is general B2B information and does not constitute a binding quotation, technical specification or guarantee."],["Orders and quotations","Product scope, MOQ, materials, branding, packaging, samples, price, payment, lead time, inspection and delivery are governed by an accepted written quotation or agreement."],["Intellectual property","Buyers must have the right to use artwork, logos and reference materials they supply. Website content may not be reproduced without permission."],["International supply","Availability and delivery depend on destination feasibility, documentation, accepted terms and shipping arrangements. Duties and compliance responsibilities are agreed per project."]]; return layout({path,title:`${h} | Leather Wallet Manufacturer`,description:`${h} for LeatherWalletManufacturer.com, operated by ${site.legalName}.`,crumbs:[["Home","/"],[h,path]],body:`${crumbs([["Home","/"],[h,path]])}<section class="page-hero page-hero--plain"><div class="shell narrow"><p class="eyebrow">Legal</p><h1>${h}</h1><p class="lede">Last updated 25 October 2026. This is a practical website policy and should be reviewed by legal counsel before production launch.</p></div></section><section class="section"><div class="shell narrow prose">${sections.map(([a,b])=>`<h2>${a}</h2><p>${b}</p>`).join("")}<h2>Contact</h2><p>Questions may be sent to <a href="mailto:${site.email}">${site.email}</a>.</p></div></section>`});}

const routes = [{path:"/",html:homeFinal()},...pages.map(p=>({path:p.path,html:genericFinal(p)})),{path:"/leather-wallet-belt-gift-set-manufacturer/",html:giftSetPageFinal()},{path:"/resources/",html:resourcesPage()},{path:"/about-us/",html:about()},{path:"/contact/",html:contactWhatsApp()},{path:"/faq/",html:faqPage()},{path:"/privacy-policy/",html:policy("privacy")},{path:"/terms-and-conditions/",html:policy("terms")}];
